/* @autogenerated */
import { EnvironmentProviders, makeEnvironmentProviders } from '@angular/core';
import {
  MAT_FORM_FIELD_DEFAULT_OPTIONS,
  MatFormFieldAppearance,
  MatFormFieldDefaultOptions,
  SubscriptSizing,
} from '@angular/material/form-field';

export interface UiDefaults {
  /** Apariencia de todos los mat-form-field; por defecto `outline`. */
  formFieldAppearance?: MatFormFieldAppearance;
  /** Reserva de espacio para hint/error bajo el campo; por defecto `fixed`. */
  subscriptSizing?: SubscriptSizing;
}

/**
 * Valores por defecto de la UI para toda la aplicación (se registra una vez en app.config.ts).
 * Un formulario concreto puede sobrescribirlos con los inputs de `<form-layout>`.
 */
export function provideUiDefaults({
  formFieldAppearance = 'outline',
  subscriptSizing = 'fixed',
}: UiDefaults = {}): EnvironmentProviders {
  return makeEnvironmentProviders([
    {
      provide: MAT_FORM_FIELD_DEFAULT_OPTIONS,
      useValue: { appearance: formFieldAppearance, subscriptSizing } satisfies MatFormFieldDefaultOptions,
    },
  ]);
}
